    // Before normalization: secondarySkill.
    char m_secondarySkill[8];         // +0x28 - movsx, so plain char
    // Before normalization: secondarySkillLevel.
    char m_secondarySkillLevel[8];    // +0x30
    // Before normalization: bCustomArmies.
